// spec: .qa/e2e/specs/registration.md
// seed: tests/seed.spec.ts
import { test, expect } from '@playwright/test';

test.describe('Регистрация', () => {
  test('RG-02 /register: чекбокс согласия с клавиатуры и aria прогресса #6a8edf78 #6a98690c @prod-safe', async ({ page }) => {
    // 1. Открыть `/register`.
    await page.goto('/register');
    const consent = page.getByRole('checkbox', { name: 'אני מאשר את תנאי השימוש ואת מדיניות הפרטיות' });
    await expect(consent).toBeVisible();
    // «שלח» неактивна, пока чекбокс не отмечен.
    const submit = page.getByRole('button', { name: 'שלח' });
    await expect(submit).toHaveAttribute('aria-disabled', 'true');

    // 2. Фокус на `[role=checkbox]`, прочитать `aria-checked`.
    await consent.focus();
    await expect(consent).toBeFocused();
    await expect(consent).toHaveAttribute('aria-checked', 'false');

    // 3. Space → true; Space ещё раз → false.
    await page.keyboard.press('Space');
    await expect(consent).toHaveAttribute('aria-checked', 'true');
    await page.keyboard.press('Space');
    await expect(consent).toHaveAttribute('aria-checked', 'false');
    await expect(submit).toHaveAttribute('aria-disabled', 'true');

    // 4. Прочитать `aria-valuemin`/`aria-valuemax`/`aria-valuenow` у `[role=progressbar]`.
    const bar = page.getByRole('progressbar');
    await expect(bar).toHaveAttribute('aria-valuemin', '1');
    await expect(bar).toHaveAttribute('aria-valuemax', '2');
    await expect(bar).toHaveAttribute('aria-valuenow', '1');
  });
});
